package br.com.fiap.bank.plataforma.controller;
import br.com.fiap.bank.plataforma.application.CreditoApplicationService; import br.com.fiap.bank.plataforma.application.dto.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import java.util.*; @CrossOrigin(origins = "http://localhost:4200") @RestController @RequestMapping("/api/v1/solicitacoes-credito") public class SolicitacaoCreditoController {private final CreditoApplicationService service;public SolicitacaoCreditoController(CreditoApplicationService s){service=s;} @PostMapping public ResponseEntity<SolicitacaoCreditoResponseDTO> criar(@Valid @RequestBody SolicitarCreditoRequest r){var saved=service.solicitar(r);return ResponseEntity.created(java.net.URI.create("/api/v1/solicitacoes-credito/"+saved.id())).body(saved);} @GetMapping public List<SolicitacaoCreditoResponseDTO> listar(@RequestParam(required=false) String cpf){return cpf==null?service.listar():service.listarPorCpf(cpf);} @GetMapping("/{id}") public SolicitacaoCreditoResponseDTO buscar(@PathVariable Long id){return service.buscar(id);} @PutMapping("/{id}/decisao") public SolicitacaoCreditoResponseDTO decidir(@PathVariable Long id,@Valid @RequestBody DecisaoCreditoRequest r){return service.decidir(id,r.decisao(),r.parecer());} }
